<?php
final class Agenda {
 public static function calendars(): array {Auth::staff();$rows=DB::all('SELECT c.id,c.name,c.color,c.account_id,c.access_role,c.selected,c.write_enabled,c.synced_at,c.last_error,a.email AS account_email,a.status AS account_status FROM calendars c LEFT JOIN google_accounts a ON a.id=c.account_id WHERE c.account_id IS NULL OR a.calendar_enabled=1 ORDER BY c.account_id,c.name');if(Auth::$user['role']!=='admin')$rows=array_values(array_filter($rows,fn($c)=>!$c['account_id']));return $rows;}
 private static function payload(array $r): array {
  unset($r['remote_json']);foreach(['attendees_json'=>'attendees','conference_json'=>'conference','attachments_json'=>'attachments'] as $field=>$target){try{$r[$target]=decode($r[$field]??null,[]);}catch(Throwable){$r[$target]=[];}unset($r[$field]);}
  return $r;
 }
 public static function list(array $p): array {$from=timestamp($p['from']??gmdate('Y-m-01'));$to=timestamp($p['to']??gmdate('Y-m-t').'T23:59:59Z');if(!$from||!$to||$from>=$to)fail('Período inválido.');$w="e.ends_at>? AND e.starts_at<? AND e.status<>'cancelled' AND c.selected=1";$a=[$from,$to];if(!empty($p['calendar_id'])){$w.=' AND e.calendar_id=?';$a[]=(int)$p['calendar_id'];}if(Auth::$user['role']!=='admin'){[$dw,$da]=Auth::demandFilter('d');$w.=' AND e.private=0 AND e.demand_id IN (SELECT d.id FROM demands d WHERE '.$dw.')';$a=[...$a,...$da];}$rows=DB::all('SELECT e.*,c.name AS calendar_name,c.color,c.account_id,c.access_role,c.write_enabled FROM events e JOIN calendars c ON c.id=e.calendar_id WHERE '.$w.' ORDER BY starts_at',$a);$seen=[];$out=[];foreach($rows as $r){$key=$r['account_id']&&$r['google_id']?$r['google_id'].'|'.$r['starts_at'].'|'.$r['title']:'local:'.$r['id'];if(isset($seen[$key]))continue;$seen[$key]=true;$out[]=self::payload($r);}return $out;}
 public static function detail(array $p): array {
  Auth::staff();$id=integer($p['id']??0,1);$r=DB::one('SELECT e.*,c.name AS calendar_name,c.color,c.account_id,c.access_role,c.write_enabled FROM events e JOIN calendars c ON c.id=e.calendar_id WHERE e.id=?',[$id]);if(!$r)fail('Compromisso não encontrado.',404);
  if(Auth::$user['role']!=='admin'){if($r['private']||!$r['demand_id'])fail('Compromisso indisponível.',403);Auth::demand((int)$r['demand_id']);}
  if($r['account_id']&&$r['google_id']&&$r['access_role']!=='freeBusyReader'){try{Google::refreshEvent($id);$r=DB::one('SELECT e.*,c.name AS calendar_name,c.color,c.account_id,c.access_role,c.write_enabled FROM events e JOIN calendars c ON c.id=e.calendar_id WHERE e.id=?',[$id])?:$r;}catch(Throwable $e){error_log('Agenda event detail refresh: '.$e->getMessage());}}
  if(($r['status']??'')==='cancelled')fail('Este compromisso foi cancelado no Google Agenda.',410);
  return self::payload($r);
 }
 public static function conflicts(string $start,string $end,int $buffer,int $exclude=0): array {$s=gmdate('Y-m-d H:i:s',strtotime($start.' UTC')-$buffer*60);$e=gmdate('Y-m-d H:i:s',strtotime($end.' UTC')+$buffer*60);$rows=DB::all("SELECT e.id,e.title,e.starts_at,e.ends_at,e.private,c.name AS calendar_name FROM events e JOIN calendars c ON c.id=e.calendar_id WHERE c.selected=1 AND e.status<>'cancelled' AND e.id<>? AND DATE_SUB(e.starts_at,INTERVAL e.buffer_minutes MINUTE)<? AND DATE_ADD(e.ends_at,INTERVAL e.buffer_minutes MINUTE)>?",[$exclude,$e,$s]);return $rows;}
 public static function save(array $p): array {Auth::admin();$id=(int)($p['id']??0);$old=$id?DB::one('SELECT * FROM events WHERE id=? FOR UPDATE',[$id]):null;if($id&&!$old)fail('Compromisso não encontrado.',404);if($old&&(int)$old['version']!==integer($p['version']??0,1))fail('O compromisso mudou. Atualize a agenda.',409);$cal=DB::one('SELECT * FROM calendars WHERE id=?',[integer($p['calendar_id']??0,1)]);if(!$cal)fail('Agenda não encontrada.');if(!$cal['write_enabled']||!in_array($cal['access_role'],['owner','writer','writerWithoutPrivateAccess']))fail('Esta agenda não permite gravação.',403);if($old&&$old['calendar_id']!=$cal['id'])fail('Para trocar de agenda, cancele o compromisso e crie outro na agenda correta.');$start=timestamp($p['starts_at']??null);$end=timestamp($p['ends_at']??null);if(!$start||!$end||$end<=$start)fail('Informe início e fim válidos.');$buffer=integer($p['buffer_minutes']??0,0,1440);$conflicts=self::conflicts($start,$end,$buffer,$id);if($conflicts&&empty($p['allow_conflict']))fail('Existe conflito de horário. Revise antes de reservar.',409,['conflicts'=>$conflicts]);$demand=!empty($p['demand_id'])?(int)$p['demand_id']:null;if($demand)Auth::demand($demand);$row=['calendar_id'=>$cal['id'],'demand_id'=>$demand,'title'=>required($p,'title',255),'starts_at'=>$start,'ends_at'=>$end,'all_day'=>(int)(bool)($p['all_day']??0),'location'=>$p['location']??'','description'=>$p['description']??'','private'=>(int)(bool)($p['private']??0),'buffer_minutes'=>$buffer,'status'=>'confirmed','sync_status'=>$cal['account_id']?'pending':'local','sync_error'=>null,'updated_at'=>now()];if($old){$row['version']=$old['version']+1;DB::update('events',$id,$row);}else{$row+=['created_at'=>now(),'google_id'=>$cal['account_id']?bin2hex(random_bytes(16)):null];$id=DB::insert('events',$row);}audit('event',$id,'save',$old,$row);$sync=$cal['account_id']?Google::syncCalendarNow((int)$cal['id']):['synced'=>true];$fresh=DB::one('SELECT sync_status,sync_error FROM events WHERE id=?',[$id]);return ['id'=>$id,'sync_status'=>$fresh['sync_status']??$row['sync_status'],'google_synced'=>(bool)($sync['synced']??false),'message'=>$cal['account_id']?(($sync['synced']??false)?'Compromisso salvo no TaskEsc e no Google Agenda.':'Compromisso salvo; o Google será tentado novamente pelo cron.'):'Compromisso salvo.'];}
 public static function cancel(array $p): array {Auth::admin();$e=DB::one('SELECT e.*,c.account_id,c.write_enabled FROM events e JOIN calendars c ON c.id=e.calendar_id WHERE e.id=? FOR UPDATE',[integer($p['id'],1)]);if(!$e)fail('Compromisso não encontrado.',404);if(!$e['write_enabled'])fail('Agenda somente leitura.',403);if((int)$e['version']!==integer($p['version']??0,1))fail('O compromisso foi alterado. Atualize.',409);DB::update('events',$e['id'],['status'=>'cancelled','version'=>$e['version']+1,'sync_status'=>$e['account_id']?'pending':'local','updated_at'=>now()]);audit('event',$e['id'],'cancelled');if($e['account_id'])Google::syncCalendarNow((int)$e['calendar_id']);return ['saved'=>true];}
 public static function calendarSave(array $p): array {Auth::admin();$id=(int)($p['id']??0);$row=['name'=>required($p,'name',190),'color'=>$p['color']??'#737373','selected'=>(int)(bool)($p['selected']??1),'write_enabled'=>(int)(bool)($p['write_enabled']??1)];if(!preg_match('/^#[a-f0-9]{6}$/i',$row['color']))fail('Cor inválida.');if($id){$c=DB::one('SELECT * FROM calendars WHERE id=?',[$id]);if(!$c)fail('Agenda não encontrada.');if(!in_array($c['access_role'],['owner','writer','writerWithoutPrivateAccess']))$row['write_enabled']=0;$row['dirty']=1;DB::update('calendars',$id,$row);}else $id=DB::insert('calendars',$row);return ['id'=>$id];}
 public static function calendarSelect(array $p): array {Auth::admin();$id=integer($p['id']??0,1);$c=DB::one('SELECT * FROM calendars WHERE id=?',[$id]);if(!$c)fail('Agenda não encontrada.',404);$selected=(int)(bool)($p['selected']??0);DB::update('calendars',$id,['selected'=>$selected,'dirty'=>$selected?1:0]);audit('calendar',$id,$selected?'selected':'unselected');return ['saved'=>true,'selected'=>$selected];}
 public static function resolve(array $p): array {Auth::admin();$e=DB::one('SELECT * FROM events WHERE id=? FOR UPDATE',[integer($p['id'],1)]);if(!$e||$e['sync_status']!=='conflict')fail('Não existe conflito pendente.');$choice=enumv($p['choice']??'',['remote','local'],'resolução');$remote=decode($e['remote_json']);if($choice==='remote'){if(($remote['status']??'')==='cancelled')$changes=['status'=>'cancelled','sync_status'=>'synced','sync_error'=>null];else $changes=Google::eventFields($remote)+['sync_status'=>'synced','sync_error'=>null];DB::update('events',$e['id'],$changes+['version'=>$e['version']+1,'updated_at'=>now()]);}else{if(($remote['status']??'')==='cancelled')fail('O evento foi excluído no Google. Crie um novo compromisso para restaurar a reserva.');DB::update('events',$e['id'],['google_etag'=>$remote['etag']??null,'sync_status'=>'pending','sync_error'=>null,'version'=>$e['version']+1]);}audit('event',$e['id'],'resolve.'.$choice);return ['saved'=>true];}
}
